class Interval {
    int start, end;
    Interval(int start, int end) { this.start = start; this.end = end; }
    @Override
    public String toString() { return "[" + start + "," + end + "]"; }
}

TreeSet<Interval> intervals = new TreeSet<>(Comparator.comparingInt(i -> i.start));
intervals.add(new Interval(1, 3));
intervals.add(new Interval(2, 6));
intervals.add(new Interval(8, 10));
intervals.add(new Interval(15, 18));

List<Interval> merged = new ArrayList<>();
for (Interval current : intervals) {
    if (!merged.isEmpty() && current.start <= merged.get(merged.size() - 1).end) {
        Interval last = merged.get(merged.size() - 1);
        last.end = Math.max(last.end, current.end);
    } else {
        merged.add(current);
    }
}
System.out.println("Po scaleniu: " + merged);

