int up = preferred, down = preferred;
while (occupied.contains(up) && up <= 100) up++;
while (occupied.contains(down) && down >= 1) down--;

int nearestFree;
if (up > 100) nearestFree = down;
else if (down < 1) nearestFree = up;
else nearestFree = (up - preferred <= preferred - down) ? up : down;

System.out.println("Najblizsze wolne miejsce do " + preferred + ": " + nearestFree);

class OrderStatisticsSet {
    private final TreeSet<Integer> set;
    OrderStatisticsSet(Collection<Integer> data) { this.set = new TreeSet<>(data); }

    int rank(int x) { return set.headSet(x, true).size(); }

    int select(int k) {
        Iterator<Integer> it = set.iterator();
        int value = 0;
        for (int i = 0; i < k; i++) value = it.next();
        return value;
    }
}

