class Interval implements Comparable<Interval> {
    int start, end;
    Interval(int start, int end) { this.start = start; this.end = end; }
    @Override
    public int compareTo(Interval o) { return Integer.compare(start, o.start); }
    @Override
    public String toString() { return "[" + start + "," + end + "]"; }
}

TreeSet<Interval> meetings = new TreeSet<>();

// Zwraca true, jesli udalo sie zarezerwowac (brak konfliktu)
java.util.function.BiPredicate<Integer, Integer> book = (start, end) -> {
    Interval probe = new Interval(start, start);
    Interval floorMeeting = meetings.floor(probe);
    Interval ceilingMeeting = meetings.ceiling(probe);
    boolean conflict = (floorMeeting != null && floorMeeting.end > start)
            || (ceilingMeeting != null && ceilingMeeting.start < end);
    if (conflict) return false;
    meetings.add(new Interval(start, end));
    return true;
};

System.out.println("Book [540,600]: " + book.test(540, 600));   // 9:00-10:00 -> true
System.out.println("Book [600,660]: " + book.test(600, 660));   // 10:00-11:00 -> true
System.out.println("Book [570,630]: " + book.test(570, 630));   // 9:30-10:30 -> false, konflikt
System.out.println("Spotkania: " + meetings);

TreeSet<Integer> filled = new TreeSet<>(List.of(3, 17, 42, 256, 999));

java.util.function.IntUnaryOperator findNearestFilled = index -> {
    Integer floorValue = filled.floor(index);
    Integer ceilingValue = filled.ceiling(index);
    if (floorValue == null) return ceilingValue;
    if (ceilingValue == null) return floorValue;
    int distFloor = index - floorValue;
    int distCeiling = ceilingValue - index;
    return (distFloor <= distCeiling) ? floorValue : ceilingValue;
};

System.out.println("Najblizszy do 20: " + findNearestFilled.applyAsInt(20));
System.out.println("Najblizszy do 500: " + findNearestFilled.applyAsInt(500));
